local BallistaMaker = {}
local PRODUCTS = {
    scorpion = { name = "Škorpijon", woodCost = 5, ironCost = 3, ropeCost = 3, gutCost = 2, time = 6, cost = 320, attack = 30, range = 250, durability = 40, description = "Majhen škorpijon za pehoto." },
    light_ballista = { name = "Lahka balista", woodCost = 7, ironCost = 4, ropeCost = 4, gutCost = 3, time = 9, cost = 750, attack = 50, range = 300, durability = 55, prestige = 3, description = "Lahka balista za hitro streljanje." },
    standard_ballista = { name = "Standardna balista", woodCost = 9, ironCost = 5, steelCost = 1, ropeCost = 5, gutCost = 4, time = 12, cost = 1600, attack = 75, range = 350, durability = 70, prestige = 6, happiness = 1, description = "Standardna balista za obleganje." },
    heavy_ballista = { name = "Težka balista", woodCost = 12, ironCost = 7, steelCost = 2, ropeCost = 6, gutCost = 5, time = 16, cost = 3200, attack = 110, range = 400, durability = 90, prestige = 12, happiness = 2, description = "Težka balista za velike oblege." },
    silver_adorned_ballista = { name = "Srebrno okrašena balista", woodCost = 12, ironCost = 6, steelCost = 3, silverCost = 2, ropeCost = 6, gutCost = 5, time = 19, cost = 5800, attack = 150, range = 450, durability = 110, prestige = 22, happiness = 4, description = "Balista s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_ballista = { name = "Kraljevski velika balista", woodCost = 18, ironCost = 9, steelCost = 5, goldCost = 3, silverCost = 2, ropeCost = 8, gutCost = 6, jewelCost = 1, time = 26, cost = 12000, attack = 220, range = 550, durability = 160, prestige = 60, happiness = 12, description = "Velika kraljevska balista z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Balistarska delavnica", cost = { gold = 500, wood = 220, stone = 200 }, upkeep = 12, qualityBonus = 5 },
    siege_yard = { name = "Oblegovalno dvorišče", cost = { gold = 1500, wood = 400, stone = 400, iron = 12 }, upkeep = 30, qualityBonus = 18 },
    tension_room = { name = "Napetilnica", cost = { gold = 3500, wood = 500, stone = 700, silver = 40, rope = 10 }, upkeep = 70, qualityBonus = 30 },
    royal_ballista_atelier = { name = "Kraljevski atelje balist", cost = { gold = 15000, wood = 1000, stone = 1500, gold = 200, jewel = 30 }, upkeep = 300, qualityBonus = 55, prestigeBonus = 50 },
}
BallistaMaker.woodStock = 22; BallistaMaker.ironStock = 14; BallistaMaker.steelStock = 10; BallistaMaker.ropeStock = 14; BallistaMaker.gutStock = 12; BallistaMaker.silverStock = 8; BallistaMaker.goldStock = 6; BallistaMaker.jewelStock = 6
BallistaMaker.productStock = {}; BallistaMaker.buildings = {}; BallistaMaker.maker = nil; BallistaMaker.activeMaking = {}; BallistaMaker.totalProducts = 0; BallistaMaker.dayTimer = 0
function BallistaMaker.init() BallistaMaker.woodStock=22; BallistaMaker.ironStock=14; BallistaMaker.steelStock=10; BallistaMaker.ropeStock=14; BallistaMaker.gutStock=12; BallistaMaker.silverStock=8; BallistaMaker.goldStock=6; BallistaMaker.jewelStock=6; BallistaMaker.productStock={}; BallistaMaker.buildings={}; BallistaMaker.maker=nil; BallistaMaker.activeMaking={}; BallistaMaker.totalProducts=0; BallistaMaker.dayTimer=0; print("[BallistaMaker] Royal Ballista Maker System initialized (6 products, 4 buildings)") end
function BallistaMaker.hireMaker(n,s) s=s or math.random(55,95); local c=700+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BallistaMaker.maker={name=n or ("Balistar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Balistar najet: %s (spretnost: %d)",BallistaMaker.maker.name,s),"success") end; return true end
function BallistaMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BallistaMaker.build(id) local ok,e=BallistaMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BallistaMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BallistaMaker.getQualityBonus() local b=0; for _,bd in ipairs(BallistaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BallistaMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BallistaMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and BallistaMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and BallistaMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.ropeCost and BallistaMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.gutCost and BallistaMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.silverCost and BallistaMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BallistaMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BallistaMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BallistaMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BallistaMaker.maker then return false,"Potreben balistar" end; return true end
function BallistaMaker.make(pt,qty) qty=qty or 1; local ok,e=BallistaMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BallistaMaker.woodStock=BallistaMaker.woodStock-d.woodCost*qty end; if d.ironCost then BallistaMaker.ironStock=BallistaMaker.ironStock-d.ironCost*qty end; if d.steelCost then BallistaMaker.steelStock=BallistaMaker.steelStock-d.steelCost*qty end; if d.ropeCost then BallistaMaker.ropeStock=BallistaMaker.ropeStock-d.ropeCost*qty end; if d.gutCost then BallistaMaker.gutStock=BallistaMaker.gutStock-d.gutCost*qty end; if d.silverCost then BallistaMaker.silverStock=BallistaMaker.silverStock-d.silverCost*qty end; if d.goldCost then BallistaMaker.goldStock=BallistaMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BallistaMaker.jewelStock=BallistaMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BallistaMaker.maker then t=math.max(1,t-math.floor(BallistaMaker.maker.skill/12)) end; table.insert(BallistaMaker.activeMaking,{id="ballista_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BallistaMaker.completeMaking(m) local q=1.0+(BallistaMaker.getQualityBonus()/100); if BallistaMaker.maker then q=q+(BallistaMaker.maker.skill/150) end; q=math.min(2.5,q); BallistaMaker.productStock[m.productType]=(BallistaMaker.productStock[m.productType] or 0)+m.quantity; BallistaMaker.totalProducts=BallistaMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BallistaMaker.maker then BallistaMaker.maker.itemsMade=BallistaMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BallistaMaker.maker.skill=math.min(100,BallistaMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Balista izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ballista.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function BallistaMaker.update(dt) if not _G.state then return end; BallistaMaker.dayTimer=BallistaMaker.dayTimer+dt; if BallistaMaker.dayTimer>=30 then BallistaMaker.dayTimer=0; for i=#BallistaMaker.activeMaking,1,-1 do local m=BallistaMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BallistaMaker.completeMaking(m); table.remove(BallistaMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BallistaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BallistaMaker.maker then tu=tu+25 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BallistaMaker.getStats() return {woodStock=BallistaMaker.woodStock,ironStock=BallistaMaker.ironStock,steelStock=BallistaMaker.steelStock,ropeStock=BallistaMaker.ropeStock,gutStock=BallistaMaker.gutStock,silverStock=BallistaMaker.silverStock,goldStock=BallistaMaker.goldStock,jewelStock=BallistaMaker.jewelStock,productStock=BallistaMaker.productStock,numBuildings=#BallistaMaker.buildings,hasMaker=BallistaMaker.maker~=nil,makerName=BallistaMaker.maker and BallistaMaker.maker.name or "—",makerSkill=BallistaMaker.maker and BallistaMaker.maker.skill or 0,activeMaking=#BallistaMaker.activeMaking,totalProducts=BallistaMaker.totalProducts} end
return BallistaMaker
